import axios from 'axios';

const API_URL = 'http://localhost:5001/api';

export const getContacts = () => {
  return axios.get(`${API_URL}/contacts`);
};

export const addContact = (contact) => {
  return axios.post(`${API_URL}/contact`, contact);
};

export const updateContact = (index, contact) => {
  return axios.put(`${API_URL}/contact/${index}`, contact);
};

export const deleteContact = (index) => {
  return axios.delete(`${API_URL}/contact/${index}`);
};
